// @FIGURE_CODE_BEGIN
var TEAL = '#1a7f92';
var SERIF = 'Georgia, "Times New Roman", serif';
var SANS = 'Helvetica, Arial, sans-serif';

var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 920, H = 580;
draw.viewbox(0, 0, W, H);

var BX0 = 30, BX1 = 620, BY = 250, BY1 = 470;
var CX = 400, L = 205;

