}
function angLabel(g, which, x, y, size, color) {
  if (which === 'c') {
    ctext(g, 'θ', x - size * 0.24, y, size, color, SERIF, true);
    ctext(g, 'c', x + size * 0.30, y + size * 0.26, size * 0.68, color, SERIF, true);
  } else {
    ctext(g, 'θ' + which, x, y, size, color, SERIF, true);
