/* ── geometry helpers ───────────────────────────────────────── */
function pt(sx, sy, r, a) { return [CX + sx * r * Math.sin(a), BY + sy * r * Math.cos(a)]; }

function arcPoly(g, r, a0, a1, sx, sy, color, dash, op) {
  var n = Math.max(3, Math.ceil(Math.abs(a1 - a0) / 0.04)), pts = [];
  for (var i = 0; i <= n; i++) {
    var a = a0 + (a1 - a0) * i / n;
    var p = pt(sx, sy, r, a);
    pts.push(p[0] + ',' + p[1]);
  }
  var pl = g.polyline(pts.join(' ')).fill('none')
    .stroke({ color: color, width: 1.4, linecap: 'round' }).opacity(op == null ? 1 : op);
  if (dash) pl.attr('stroke-dasharray', '4,3');
  return pl;
}

function arrowAt(g, x, y, dx, dy, size, color, op) {
  var m = Math.hypot(dx, dy); if (!m) return;
  var ux = dx / m, uy = dy / m, px = -uy, py = ux;
  var p1 = [x + ux * size, y + uy * size];
  var p2 = [x - ux * size * 0.65 + px * size * 0.60, y - uy * size * 0.65 + py * size * 0.60];
  var p3 = [x - ux * size * 0.65 - px * size * 0.60, y - uy * size * 0.65 - py * size * 0.60];
  g.polygon([p1, p2, p3].map(function (p) { return p[0] + ',' + p[1]; }).join(' '))
    .fill(color).opacity(op == null ? 1 : op);
}

function leader(g, x0, y0, x1, y1) {
  var mx = (x0 + x1) / 2, my = (y0 + y1) / 2 - 20;
  g.path('M' + x0 + ',' + y0 + ' Q' + mx + ',' + my + ' ' + x1 + ',' + y1)
    .fill('none').stroke({ color: '#222', width: 1.2 });
  g.circle(4.6).center(x1, y1).fill('#222');
}

function interactive(el, tip, title, body) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () { showPopup(title, body); });
  return el;
}

/* ── main render ────────────────────────────────────────────── */
function render() {
  dyn.clear();

  var d1 = state.theta1, ratio = state.ratio;
  var t1 = d1 * Math.PI / 180;
  var tc = Math.asin(Math.min(1, ratio)), dc = tc * 180 / Math.PI;
  var s2 = Math.sin(t1) / ratio;
  var tir = s2 > 1;
  var t2 = tir ? null : Math.asin(Math.min(1, s2));
  var grazing = Math.abs(d1 - dc) < 0.8;
  var regime = grazing ? 'b' : (tir ? 'c' : 'a');

  /* critical-angle reference ray (dashed) */
  if (state.showRef) {
    var cs = pt(-1, 1, L * 0.95, tc);
    interactive(
      dyn.line(cs[0], cs[1], CX, BY).stroke({ color: TEAL, width: 2, dasharray: '7,5', linecap: 'round' }).opacity(0.8),
      'θc = ' + dc.toFixed(1) + '°  (sin θc = n₂/n₁ = ' + ratio.toFixed(2) + ')',
      'The critical angle',
      'This dashed ray sits exactly at θc, where sin θc = n₂/n₁. Any incident ray inside this angle still escapes; any ray outside it is totally internally reflected. Changing n₂/n₁ swings this reference line.');
    if (dc > 3) {
      arcPoly(dyn, 82, 0, tc, -1, 1, TEAL, true, 0.85);
      var cl = pt(-1, 1, 103, tc / 2);
      angLabel(dyn, 'c', cl[0], cl[1], 19, TEAL);
    }
  }

  /* refracted ray */
  if (!tir) {
    var opR = 1 - 0.45 * Math.min(1, t1 / Math.max(tc, 1e-6));
    var R = pt(1, -1, L, t2);
    var lr = interactive(
      dyn.line(CX, BY, R[0], R[1]).stroke({ color: TEAL, width: 2.6, linecap: 'round' }).opacity(opR),
      'Refracted ray: θ₂ = ' + (t2 * 180 / Math.PI).toFixed(1) + '°',
      'Refracted ray',
      'The transmitted ray bends away from the normal because it enters the less dense medium (n₂ < n₁). As θ₁ grows, θ₂ grows much faster and flattens onto the surface.');
    var mR = pt(1, -1, L * 0.52, t2);
    arrowAt(dyn, mR[0], mR[1], Math.sin(t2), -Math.cos(t2), 9, TEAL, opR);
    if (t2 > 0.05) {
      arcPoly(dyn, 60, 0, t2, 1, -1, TEAL, false, 0.95);
      var l2 = pt(1, -1, 80, Math.max(t2 / 2, 0.20));
      angLabel(dyn, '₂', l2[0], l2[1], 19, '#222');
    }
    // "Refracted ray" label with leader
    var lp = pt(1, -1, L * 0.78, t2);
    ctext(dyn, 'Refracted ray', 196, 50, 15, '#222');
    leader(dyn, 246, 60, lp[0], lp[1]);
  }

  /* grazing: right-angle marker + θ₂ = 90° */
  if (grazing) {
    dyn.path('M' + (CX + 18) + ',' + BY + ' L' + (CX + 18) + ',' + (BY - 18) + ' L' + CX + ',' + (BY - 18))
      .fill('none').stroke({ color: '#222', width: 1.6 });
    ctext(dyn, 'θ₂ = 90°', CX + 88, BY - 30, 17, '#222', SERIF, true, 'bold');
  }

  /* reflected ray */
  var opRef = tir ? 1 : (0.5 + 0.5 * Math.min(1, t1 / Math.max(tc, 1e-6)));
  var E = pt(1, 1, L, t1);
  interactive(
    dyn.line(CX, BY, E[0], E[1]).stroke({ color: TEAL, width: 2.6, linecap: 'round' }).opacity(opRef),
    'Reflected ray: leaves at θ₁ = ' + d1.toFixed(0) + '° (always)',
    'Reflected ray',
    'Reflection obeys θ_reflected = θ_incident at every angle. As θ₁ approaches and passes θc, more and more of the energy ends up in this ray — beyond θc it carries all of it.');
  var mE = pt(1, 1, L * 0.52, t1);
  arrowAt(dyn, mE[0], mE[1], Math.sin(t1), Math.cos(t1), 9, TEAL, opRef);

  /* incident ray */
  var S = pt(-1, 1, L, t1);
  interactive(
    dyn.line(S[0], S[1], CX, BY).stroke({ color: TEAL, width: 2.6, linecap: 'round' }),
    'Incident ray inside n₁: θ₁ = ' + d1.toFixed(0) + '°',
    'Incident ray',
    'The ray travels up through the denser medium n₁ and hits the boundary at θ₁ measured from the normal. The slider tilts this ray; everything else follows from Snell\'s law.');
  var mS = pt(-1, 1, L * 0.52, t1);
  arrowAt(dyn, mS[0], mS[1], Math.sin(t1), -Math.cos(t1), 9, TEAL, 1);

  /* θ₁ arcs and labels below the boundary */
  if (d1 > 1.5) {
    arcPoly(dyn, 50, 0, t1, -1, 1, TEAL, false, 0.95);
    arcPoly(dyn, 50, 0, t1, 1, 1, TEAL, false, 0.95);
  }
  var lA = pt(-1, 1, 70, Math.max(t1 / 2, 0.22));
  var lB = pt(1, 1, 70, Math.max(t1 / 2, 0.22));
  angLabel(dyn, '₁', lA[0], lA[1], 19, '#222');
  angLabel(dyn, '₁', lB[0], lB[1], 19, '#222');

  /* ray text labels with leaders */
  var ip = pt(-1, 1, L * 0.62, t1);
  ctext(dyn, 'Incident ray', 82, 216, 15, '#222');
  leader(dyn, 116, 228, ip[0], ip[1]);

  var rp = pt(1, 1, L * 0.70, t1);
  ctext(dyn, 'Reflected ray', 352, 508, 15, '#222');
  leader(dyn, 372, 496, rp[0], rp[1]);

  /* total internal reflection annotation */
  if (tir) {
    ctext(dyn, 'Total internal', 543, 404, 16, '#123', SANS, false, 'bold');
    ctext(dyn, 'reflection', 543, 427, 16, '#123', SANS, false, 'bold');
  }

  /* ── readout ── */
  var rx = 664, y0 = 52, lh = 25;
  ltext(dyn, 'θ₁ = ' + d1.toFixed(0) + '°', rx, y0, 14, '#222');
  if (tir) {
    ltext(dyn, 'θ₂ = — (no refracted ray)', rx, y0 + lh, 14, '#c0392b', 'bold');
  } else {
    ltext(dyn, 'θ₂ = ' + (t2 * 180 / Math.PI).toFixed(1) + '°', rx, y0 + lh, 14, '#222');
  }
  ltext(dyn, 'n₂/n₁ = ' + ratio.toFixed(2), rx, y0 + 2 * lh, 14, '#222');
  ltext(dyn, 'θc = ' + dc.toFixed(1) + '°', rx, y0 + 3 * lh, 14, TEAL, 'bold');

  ltext(dyn, 'n₁ sin θ₁ = n₂ sin θ₂', rx, y0 + 4 * lh + 10, 14, tir ? '#c0392b' : '#222');
  ltext(dyn, 'sin θ₂ = sin θ₁ /(n₂/n₁) = ' + s2.toFixed(2) + (tir ? '  > 1 ✗' : ''),
    rx, y0 + 5 * lh + 10, 13, tir ? '#c0392b' : '#444', tir ? 'bold' : 'normal');
  ltext(dyn, 'sin θc = n₂/n₁ = ' + ratio.toFixed(2), rx, y0 + 6 * lh + 10, 13, '#444');

  /* ── regime captions ── */
  var caps = [
    ['a', '(a) partial refraction', 150],
    ['b', '(b) grazing: θ₂ = 90°', 400],
    ['c', '(c) total internal reflection', 680]
  ];
  for (var i = 0; i < caps.length; i++) {
    var on = (caps[i][0] === regime);
    var ct = ctext(dyn, caps[i][1], caps[i][2], 548, on ? 16 : 14,
      on ? TEAL : '#9aa5ab', SANS, false, on ? 'bold' : 'normal');
    if (on) dyn.line(caps[i][2] - 78, 564, caps[i][2] + 78, 564).stroke({ color: TEAL, width: 2 });
    (function (txt, k) {
      interactive(txt, 'Current regime indicator',
        'Three regimes, one slider',
        'The original figure showed these as three separate panels. They are really one continuous story: below θc light partially refracts, exactly at θc the refracted ray grazes the surface (θ₂ = 90°), and above θc no refracted ray exists at all.');
    })(ct, i);
  }
}

